/bin/bash -lc "node --input-type=module <<'EOF'
const origin = 'http://localhost:3117'
const cases = [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp?currency=USD', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
  ['/products/vase', 'Stone vase', 'USD 80.00', 'Brass lamp'],
]
for (const [path, name, price, related] of cases) {
  const response = await fetch(origin + path)
  const html = await response.text()
  const checks = {
    frame: html.includes('Signal Shop collection'),
    name: html.includes("'`<h1>${name}</h1>`),
    price: html.includes(price),
    related: html.includes(related),
  }
  console.log(path, response.status, checks)
  if (response.status !== 200 || Object.values(checks).some((value) => !value)) process.exitCode = 1
}
const response = await fetch(origin + '"'/products/lamp?currency=EUR')
const reader = response.body.getReader()
const decoder = new TextDecoder()
let html = ''
let chunk = 0
const seen = {}
const start = Date.now()
while (true) {
  const { done, value } = await reader.read()
  if (done) break
  chunk++
  html += decoder.decode(value, { stream: true })
  for (const [label, marker] of Object.entries({ frame: 'Signal Shop collection', product: '<h1>Brass lamp</h1>', related: '<h2>Related products</h2><p><a' })) {
    if (seen[label] === undefined && html.includes(marker)) seen[label] = { chunk, ms: Date.now() - start }
  }
}
console.log('stream order:', seen)
if ("'!(seen.frame?.chunk < seen.product?.chunk && seen.product?.chunk < seen.related?.chunk)) process.exitCode = 1
EOF'

